t.script:
        (function () {
            'use strict';

            /* ── State ─────────────────────────────────────────────────────── */
            var sessionUuid  = null;
            var lastMsgId    = 0;   /* FIX: initialised from server on session reuse */
            var pollTimer    = null;
            var patientName  = '';
            var patientPhone = '';
            var patientSpec  = '';
            var patientSlot  = '';

            /* ── Utility ────────────────────────────────────────────────────── */
            function esc(t) {
                var d = document.createElement('div');
                d.textContent = String(t || '');
                return d.innerHTML;
            }
            function nowStr() {
                return new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            }
            function post(url, payload) {
                return fetch(url, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                    },
                    body: JSON.stringify(payload || {}),
                })
                .then(function (r) {
                    if (!r.ok) throw new Error('HTTP ' + r.status);
                    return r.json();
                });
            }

            /* ── Form error — shown BELOW the button ────────────────────────── */
            function showFormError(msg) {
                var el = document.getElementById('pc-form-error');
                if (!el) return;
                el.textContent = '⚠ ' + msg;
                el.style.display = 'block';
            }
            function clearFormError() {
                var el = document.getElementById('pc-form-error');
                if (el) { el.style.display = 'none'; el.textContent = ''; }
            }

            /* ── Bubble renderer ─────────────────────────────────────────────── */
            function addBubble(type, senderName, text) {
                var box = document.getElementById('pc-messages');
                if (!box) return;
                var wrap = document.createElement('div');

                if (type === 'system') {
                    wrap.className = 'pc-bubble-wrap';
                    wrap.innerHTML = '
' + esc(text) + '';
                } else if (type === 'patient') {
                    wrap.className = 'pc-bubble-wrap pc-right';
                    var initP = (patientName || 'P')[0].toUpperCase();
                    wrap.innerHTML =
                        '
' +
                            esc(text) +
                            '
' + nowStr() + ' · Sent' +
                        '' +
                        '
' + esc(initP) + '';
                } else {
                    wrap.className = 'pc-bubble-wrap';
                    var clean = (senderName || 'Doctor').replace(/^Dr\.?\s*/i, '');
                    var initD = clean.substring(0, 2).toUpperCase();
                    wrap.innerHTML =
                        '
' + esc(initD) + '' +
                        '
' +
                            '
Dr. ' + esc(clean) + '' +
                            esc(text) +
                            '
' + nowStr() + '' +
                        '';
                }
                box.appendChild(wrap);
                box.scrollTop = box.scrollHeight;
            }

            /* ── Update doctor header + status bar ───────────────────────────── */
            function setConnected(doctorName) {
                var status = document.getElementById('pc-status');
                var title  = document.getElementById('pc-doctor-title');
                var sub    = document.getElementById('pc-chat-sub');
                var avatar = document.getElementById('pc-chat-avatar');
                var clean  = (doctorName || '').replace(/^Dr\.?\s*/i, '');
                var initials = clean.substring(0, 2).toUpperCase() || 'Dr';
                if (avatar) avatar.textContent = initials;
                if (title)  title.textContent  = 'Dr. ' + clean;
                if (sub)    sub.textContent    = 'Online';
                if (status) {
                    status.textContent = '🟢 Dr. ' + clean + ' has joined your consultation';
                    status.className   = 'pc-connected';
                }
            }

            /* ── Dynamic slot fetch ──────────────────────────────────────────── */
            function fetchSlots(spec) {
                var slotSel = document.getElementById('pc-slot');
                var loading = document.getElementById('pc-slot-loading');

                /* Reset to safe defaults */
                slotSel.innerHTML = '— Any available time —';
                slotSel.disabled  = true;
                if (loading) loading.style.display = 'none';

                if (!spec) {
                    slotSel.innerHTML = '— Select specialization first —';
                    return;
                }

                if (loading) loading.style.display = 'block';

                post('/get_chat_slots', { specialization: spec })
                .then(function (data) {
                    if (loading) loading.style.display = 'none';
                    var result = (data && data.result) || {};
                    var slots  = result.slots || [];

                    /* If no slots — silently leave "Any available time" selected.
                       Do NOT show an error since time slot is optional. */
                    if (slots.length > 0) {
                        slots.forEach(function (s) {
                            var opt = document.createElement('option');
                            opt.value       = s.name;
                            opt.textContent = s.name;
                            slotSel.appendChild(opt);
                        });
                    }
                    slotSel.disabled = false;
                })
                .catch(function (err) {
                    /* On any error — silently enable with "Any available time" */
                    if (loading) loading.style.display = 'none';
                    slotSel.disabled = false;
                    console.warn('[PatientChat] Slot fetch failed (non-critical):', err);
                });
            }

            /* ── Polling ────────────────────────────────────────────────────── */
            function pollMessages() {
                if (!sessionUuid) return;
                post('/clinic/patient/chat/poll', {
                    session_id: sessionUuid,
                    last_id:    lastMsgId,
                })
                .then(function (data) {
                    var res  = (data && data.result) || {};
                    var msgs = res.messages || [];

                    msgs.forEach(function (m) {
                        addBubble(m.sender, m.sender_name, m.message);
                        if (m.id > lastMsgId) lastMsgId = m.id;
                    });

                    if (res.doctor_assigned && res.doctor_name) {
                        setConnected(res.doctor_name);
                    }
                    if (res.status === 'ended' || res.status === 'closed') {
                        clearInterval(pollTimer); pollTimer = null;
                        addBubble('system', '', '🏁 Consultation has ended. Thank you!');
                        document.getElementById('pc-send-btn').disabled = true;
                        document.getElementById('pc-msg-input').disabled = true;
                        document.getElementById('pc-msg-input').placeholder = 'Consultation ended.';
                    }
                })
                .catch(function (e) { console.error('[PatientChat] Poll error:', e); });
            }

            function startPolling() {
                if (pollTimer) clearInterval(pollTimer);
                pollMessages();
                pollTimer = setInterval(pollMessages, 3000);
            }

            /* ── Start chat ──────────────────────────────────────────────────── */
            function doStart() {
                var btn = document.getElementById('pc-start-btn');
                clearFormError();

                patientName  = ((document.getElementById('pc-name')  || {}).value || '').trim();
                patientPhone = ((document.getElementById('pc-phone') || {}).value || '').trim();
                patientSpec  = ((document.getElementById('pc-spec')  || {}).value || '').trim();
                patientSlot  = ((document.getElementById('pc-slot')  || {}).value || '').trim();

                /* Validation: shown BELOW button, never blocks filled fields visually */
                if (!patientName) {
                    showFormError('Please enter your full name.');
                    return;
                }
                if (!patientPhone) {
                    showFormError('Please enter your phone number.');
                    return;
                }
                if (patientPhone.replace(/\D/g, '').length !== 10) {
                    showFormError('Please enter a valid 10-digit phone number.');
                    return;
                }
                if (!patientSpec) {
                    showFormError('Please select a specialization.');
                    return;
                }

                btn.disabled     = true;
                btn.textContent  = '⏳ Connecting…';

                post('/clinic/patient/chat/start', {
                    patient_name:   patientName,
                    patient_phone:  patientPhone,
                    specialization: patientSpec,
                    preferred_slot: patientSlot,
                })
                .then(function (data) {
                    var res = (data && data.result) || {};

                    if (res.error) {
                        showFormError(res.error);
                        btn.disabled    = false;
                        btn.textContent = 'Start Consultation →';
                        return;
                    }

                    sessionUuid = res.session_id;

                    /*
                     * FIX — PREVIOUS MESSAGES BUG:
                     * If the server reused an existing session (same phone number),
                     * it returns last_message_id = the highest existing message ID.
                     * We set lastMsgId to that value so polling only fetches NEW
                     * messages written AFTER this consultation started.
                     * Fresh sessions return last_message_id = 0 (or the greeting ID).
                     */
                    lastMsgId = res.last_message_id || 0;

                    /* Switch to chat view */
                    document.getElementById('pc-step1').style.display = 'none';
                    document.getElementById('pc-step2').style.display = 'block';

                    /*
                     * FIX — DUPLICATE MESSAGE:
                     * Show ONLY res.greeting which already contains the slot note.
                     * We do NOT add a second slot bubble here.
                     */
                    if (res.greeting) {
                        addBubble('system', '', res.greeting);
                    }

                    if (res.doctor_assigned && res.doctor_name) {
                        setConnected(res.doctor_name);
                    }

                    startPolling();
                })
                .catch(function (e) {
                    console.error('[PatientChat] Start error:', e);
                    showFormError('Connection error — please try again.');
                    btn.disabled    = false;
                    btn.textContent = 'Start Consultation →';
                });
            }

            /* ── Send message ─────────────────────────────────────────────────── */
            function doSend() {
                var input = document.getElementById('pc-msg-input');
                var msg   = input ? input.value.trim() : '';
                if (!msg || !sessionUuid) return;

                addBubble('patient', patientName, msg);
                input.value = '';

                post('/clinic/patient/chat/send', {
                    session_id:   sessionUuid,
                    message:      msg,
                    patient_name: patientName,
                })
                .then(function (data) {
                    var res = (data && data.result) || {};
                    if (res.error) { addBubble('system', '', '⚠ ' + res.error); return; }
                    if (res.doctor_assigned && res.doctor_name) setConnected(res.doctor_name);
                    if (res.status === 'ended' || res.status === 'closed') {
                        clearInterval(pollTimer);
                        addBubble('system', '', '🏁 Consultation has ended.');
                        document.getElementById('pc-send-btn').disabled = true;
                        document.getElementById('pc-msg-input').disabled = true;
                    }
                })
                .catch(function () {
                    addBubble('system', '', '⚠ Network error. Please try again.');
                });
            }

            /* ── Wire DOM events ─────────────────────────────────────────────── */
            function init() {
                var startBtn = document.getElementById('pc-start-btn');
                var sendBtn  = document.getElementById('pc-send-btn');
                var specSel  = document.getElementById('pc-spec');
                var msgInput = document.getElementById('pc-msg-input');

                if (startBtn) startBtn.addEventListener('click', doStart);
                if (sendBtn)  sendBtn.addEventListener('click', doSend);
                if (msgInput) {
                    msgInput.addEventListener('keypress', function (e) {
                        if (e.key === 'Enter') doSend();
                    });
                }
                if (specSel) {
                    specSel.addEventListener('change', function () {
                        fetchSlots(this.value);
                    });
                }
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', init);
            } else {
                init();
            }
        })();
